SELECT w.web_name, hd.hd_dep_count, sm.sm_type, SUM(ws.ws_net_paid) AS net_paid, MIN(ws.ws_ext_tax) AS min_tax, ROW_NUMBER() OVER (ORDER BY SUM(ws.ws_net_paid) DESC) AS overall_rank FROM web_sales ws JOIN web_site w ON ws.ws_web_site_sk = w.web_site_sk JOIN household_demographics hd ON ws.ws_ship_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE ws.ws_ext_discount_amt < 10 GROUP BY w.web_name, hd.hd_dep_count, sm.sm_type HAVING MIN(ws.ws_ext_tax) IS NOT NULL ORDER BY overall_rank LIMIT 10
